"""Format identification helpers for Ancient's command line interface."""

def identify(data: bytes):
    """Return Ancient's human-readable compression description, or None."""
    if data.startswith(b'\x1f\x8b') and len(data) >= 11:
        # Accept one or more complete members; reject arbitrary trailing bytes.
        try:
            import zlib
            rest = data
            first_plain = None
            while rest:
                if not rest.startswith(b'\x1f\x8b'):
                    raise ValueError("trailing data")
                decoder = zlib.decompressobj(16 + zlib.MAX_WBITS)
                plain = decoder.decompress(rest) + decoder.flush()
                if not decoder.eof:
                    raise ValueError("truncated stream")
                if first_plain is None:
                    first_plain = plain
                rest = decoder.unused_data
            if first_plain:
                return 'gzip: Deflate'
        except Exception:
            pass
    if data.startswith(b'BZh') and len(data) >= 4 and data[3:4] in b'123456789':
        return 'bz2: bzip2'
    # Unix compress requires a valid LZW stream, not just its two-byte magic.
    if data.startswith(b'\x1f\x9d'):
        try:
            from unixcompress import decompress
            decompress(data)
            return 'Z: Compress'
        except Exception:
            pass
    if data.startswith(b'\x1f\xa0') and len(data) >= 4:
        return 'SCO Compress LZH'
    return None
