"""Small standard-library decoder backends used by the command line frontend."""
import bz2
import gzip
import zlib
import unixcompress


def decode(data: bytes):
    """Return (human-readable format, uncompressed bytes), or None if unsupported.

    Format recognition deliberately uses stream magic; filenames do not influence
    decompression.  gzip.decompress and bz2.decompress both accept concatenated
    members, as the reference utility does for ordinary streams.
    """
    if data.startswith(b'\x1f\x8b'):
        try:
            # Ancient rejects incomplete streams, junk after the last member,
            # and members which produce no bytes.  Decode the first member,
            # while validating any following members as well.
            rest = data
            first = None
            while rest:
                if not rest.startswith(b'\x1f\x8b'):
                    return None
                dec = zlib.decompressobj(16 + zlib.MAX_WBITS)
                plain = dec.decompress(rest) + dec.flush()
                if not dec.eof:
                    return None
                if first is None:
                    first = plain
                rest = dec.unused_data
            if not first:
                return None
            return 'gzip: Deflate', first
        except (OSError, EOFError, zlib.error, ValueError):
            return None
    if data.startswith(b'BZh'):
        # Ancient only treats the signature as a bzip stream when the
        # mandatory block-size digit is present and in range.
        if len(data) < 4 or data[3:4] not in b'123456789':
            return None
        try:
            dec = bz2.BZ2Decompressor()
            plain = dec.decompress(data)
            if not dec.eof:
                return 'bz2: bzip2', None
            return 'bz2: bzip2', plain
        except (OSError, EOFError, ValueError):
            return 'bz2: bzip2', None
    if data.startswith(b'\x1f\x9d'):
        try:
            return 'Z: Compress', unixcompress.decompress(data)
        except (ValueError, IndexError):
            return 'Z: Compress', None
    return None
"""Format identification helpers for Ancient's command line interface."""

def identify(data: bytes):
    """Return Ancient's human-readable compression description, or None."""
    if data.startswith(b'\x1f\x8b') and len(data) >= 11:
        # Accept one or more complete members; reject arbitrary trailing bytes.
        try:
            import zlib
            rest = data
            first_plain = None
            while rest:
                if not rest.startswith(b'\x1f\x8b'):
                    raise ValueError("trailing data")
                decoder = zlib.decompressobj(16 + zlib.MAX_WBITS)
                plain = decoder.decompress(rest) + decoder.flush()
                if not decoder.eof:
                    raise ValueError("truncated stream")
                if not plain:
                    raise ValueError("empty member")
                if first_plain is None:
                    first_plain = plain
                rest = decoder.unused_data
            if first_plain:
                return 'gzip: Deflate'
        except Exception:
            pass
    if data.startswith(b'BZh') and len(data) >= 4 and data[3:4] in b'123456789':
        return 'bz2: bzip2'
    # Unix compress requires a valid LZW stream, not just its two-byte magic.
    if data.startswith(b'\x1f\x9d'):
        try:
            from unixcompress import decompress
            decompress(data)
            return 'Z: Compress (new)' if data[2] & 0x80 else 'Z: Compress (old)'
        except Exception:
            pass
    if data.startswith(b'\x1f\xa0') and len(data) >= 4:
        return 'SCO Compress LZH'
    if data.startswith(b'XPKF') and len(data) >= 36:
        return 'XPK: XPK'
    if data.startswith(b'RNC\x01'):
        return 'RNC: Rob Northen Compressor (RNC1)'
    if data.startswith(b'RNC\x02'):
        return 'RNC: Rob Northen Compressor (RNC2)'
    if data.startswith(b'DMS!'):
        return 'DMS: Disk Masher System'
    if data.startswith(b'ziRCONia'):
        return 'MMCMP: Music Module Compressor'
    if data.startswith(b'PP20'):
        return 'PowerPacker'
    if data.startswith(b'ICE!'):
        return 'Pack-Ice'
    return None
"""Decoder for the Unix compress (.Z) LZW stream format."""

class InvalidCompress(ValueError):
    pass


def decompress(data: bytes) -> bytes:
    if len(data) < 3 or data[:2] != b"\x1f\x9d":
        raise InvalidCompress("invalid compress header")
    flags = data[2]
    maxbits = flags & 0x1f
    block = bool(flags & 0x80)
    if flags & 0x60 or maxbits < 9 or maxbits > 16:
        raise InvalidCompress("invalid compress flags")
    src = data[3:]
    out = bytearray()
    width = 9
    limit = 1 << width
    maxcode = (1 << maxbits) - 1
    clear = 256 if block else -1
    nextcode = 257 if block else 256
    table = [bytes([i]) for i in range(256)] + [None] * ((1 << maxbits) - 256)
    bitpos = 0
    old = None

    def code_at(pos, bits):
        # Compress packs codes least-significant bit first into width-sized
        # groups.  Width changes begin at a group boundary.
        group = (pos // (bits * 8)) * bits
        off = pos - group * 8
        if group + bits > len(src):
            return None
        val = int.from_bytes(src[group:group + bits], "little")
        return (val >> off) & ((1 << bits) - 1)

    while True:
        code = code_at(bitpos, width)
        if code is None:
            break
        bitpos += width
        if code == clear:
            width = 9
            limit = 1 << width
            nextcode = 257
            old = None
            continue
        if code > nextcode or code >= len(table):
            raise InvalidCompress("invalid LZW code")
        if old is None:
            if code >= 256 or table[code] is None:
                raise InvalidCompress("invalid initial code")
            entry = table[code]
            out.extend(entry)
            old = entry
            continue
        if code < nextcode and table[code] is not None:
            entry = table[code]
        elif code == nextcode:
            entry = old + old[:1]
        else:
            raise InvalidCompress("invalid LZW code")
        out.extend(entry)
        if nextcode <= maxcode:
            table[nextcode] = old + entry[:1]
            nextcode += 1
            if nextcode >= limit and width < maxbits:
                width += 1
                limit = 1 << width
        old = entry
    if not out:
        raise InvalidCompress("empty compress stream")
    return bytes(out)

