def _gzip_stream(data: bytes) -> bool:
    """Check gzip's header and DEFLATE members without requiring the size word.

    Ancient's legacy gzip path accepts a missing trailer and a trailer with a
    complete CRC but a short size field.  Bytes after a partial CRC are rejected.
    """
    import zlib
    rest = data
    members = 0
    last_plain = None
    while rest:
        if len(rest) < 10 or rest[:2] != b'\x1f\x8b' or rest[2] != 8:
            return False
        flags = rest[3]
        if flags & 0xe0:
            return False
        pos = 10
        if flags & 4:
            if pos + 2 > len(rest): return False
            size = int.from_bytes(rest[pos:pos+2], 'little')
            pos += 2 + size
        for mask in (8, 16):
            if flags & mask:
                end = rest.find(b'\0', pos)
                if end < 0: return False
                pos = end + 1
        if flags & 2: pos += 2
        if pos >= len(rest): return False
        dec = zlib.decompressobj(-zlib.MAX_WBITS)
        try:
            plain = dec.decompress(rest[pos:])
        except zlib.error:
            return False
        if not dec.eof:
            return False
        last_plain = plain
        trailer_and_rest = dec.unused_data
        members += 1
        if not trailer_and_rest:
