"""Format identification helpers for Ancient's command line interface."""
import zlib

class _PartialDeflateError(ValueError):
    def __init__(self, output):
        self.output = output


def _gzip_member(data):
    if len(data) < 10 or data[:2] != b'\x1f\x8b' or data[2] != 8:
        raise ValueError('invalid gzip header')
    flags = data[3]
    if flags & 0xe0:
        raise ValueError('reserved gzip flags')
    pos = 10
    if flags & 4:
        if pos + 2 > len(data): raise ValueError('short gzip extra length')
        pos += 2 + int.from_bytes(data[pos:pos + 2], 'little')
    for mask in (8, 16):
        if flags & mask:
            end = data.find(b'\0', pos)
            if end < 0: raise ValueError('unterminated gzip field')
            pos = end + 1
    if flags & 2: pos += 2
    if pos >= len(data): raise ValueError('short gzip header')
    dec = zlib.decompressobj(-zlib.MAX_WBITS)
    try:
        plain = dec.decompress(data[pos:])
    except zlib.error:
        # The reference recognizer can keep output emitted before a later
        # malformed DEFLATE block. Python's bulk call raises and loses it.
        dec = zlib.decompressobj(-zlib.MAX_WBITS)
        partial = bytearray()
        try:
            for byte in data[pos:]:
                partial.extend(dec.decompress(bytes((byte,))))
        except zlib.error:
            raise _PartialDeflateError(bytes(partial))
        raise
    if not dec.eof:
        raise ValueError('incomplete deflate stream')
    return plain, dec.unused_data, len(data) - pos - len(dec.unused_data)


def identify(data: bytes):
    """Return Ancient's human-readable compression description, or None."""
    if data.startswith(b'\x1f\x8b') and len(data) >= 11:
        try:
            rest = data
            last_plain = b''
            while rest:
                try:
                    plain, trailer, raw_length = _gzip_member(rest)
                except _PartialDeflateError as err:
                    size = int.from_bytes(rest[-4:], 'little') if len(rest) >= 18 else 0
                    if 0 < size <= len(rest):
                        return 'gzip: Deflate'
                    raise
                if len(trailer) >= 18 and trailer[8:10] == b'\x1f\x8b':
                    last_plain = plain
                    rest = trailer[8:]
                    continue
                allowed = (len(trailer) in (6, 7, 8)
                           or (len(trailer) == 5 and len(plain) <= 7)
                           or (len(trailer) == 0 and raw_length >= 8))
                if not allowed:
                    raise ValueError('invalid gzip trailer length')
                last_plain = plain
                rest = ''
            if last_plain:
                return 'gzip: Deflate'
        except Exception:
            pass
    if data.startswith(b'BZh') and len(data) >= 4 and data[3:4] in b'123456789':
        return 'bz2: bzip2'
    if data.startswith(b'\x1f\x1e') and len(data) >= 6:
        # Unix Pack stores its expected output size as a big-endian word.
        if int.from_bytes(data[2:6], 'big') <= (1 << 27):
            return 'z: Pack'
    if data.startswith(b'\x1f\x9e'):
        return 'F: Freeze/Melt 1.x'
    if data.startswith(b'\x1f\x9d'):
        try:
            from unixcompress import decompress
            decompress(data)
            return 'Z: Compress (new)' if data[2] & 0x80 else 'Z: Compress (old)'
        except Exception:
            pass
    if data.startswith(b'\x1f\xa0') and len(data) >= 4:
        return 'SCO Compress LZH'
    return None

